Object.keys(overrides).forEach(lang => {
  if (resources[lang] && resources[lang].translation) {
    Object.assign(resources[lang].translation, overrides[lang]);
  }
});


i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: localStorage.getItem('watch_language') || "en", // persist language choice
    fallbackLng: "en",
    interpolation: {
      escapeValue: false
    }
  });

export default i18n;
